const input = $input.first().json || {};
const headers = input.headers || {};
const sourceIp = (input.source_ip
  || headers['x-real-ip']
  || (headers['x-forwarded-for'] || '').toString().split(',')[0].trim()
  || 'unknown').slice(0, 64);
const userAgent = (input.user_agent || headers['user-agent'] || 'unknown').toString().slice(0, 500);
const endpoint = (input.endpoint || 'unknown').toString().slice(0, 80);
const maxPerMinute = Number.isFinite(input.max_per_minute) ? input.max_per_minute : 30;
const projectId = input.project_id || null;
const agentName = input.agent_name || 'webhook_entry';
return [{ json: { source_ip: sourceIp, user_agent: userAgent, endpoint, max_per_minute: maxPerMinute, project_id: projectId, agent_name: agentName } }];

