WITH rl AS (
  SELECT CASE WHEN allowed THEN 'allowed' ELSE 'blocked' END AS verdict, reason FROM check_rate_limit($1::text, $2::text, $3::int, ($3::int * 60))
), valid_pid AS (
  SELECT id FROM projects WHERE id = NULLIF($4,'')::uuid
), log AS (
  INSERT INTO activity_log (project_id, agent_name, action, status, source_ip, user_agent, input_summary)
  VALUES ((SELECT id FROM valid_pid), $5, 'webhook_received', 'success', $1, $6,
          format('endpoint=%s rate_limit_max=%s', $2, $3))
  RETURNING id
)
SELECT rl.verdict AS verdict, log.id AS log_id FROM rl, log;

