const dbRow = $input.first().json || {};
const input = $('Normalize Input').first().json;
const verdict = dbRow.verdict || 'allowed';
const allowed = verdict !== 'blocked';
const out = {
  allowed,
  blocked: !allowed,
  verdict,
  source_ip: input.source_ip,
  user_agent: input.user_agent,
  endpoint: input.endpoint,
  log_id: dbRow.log_id || null
};
return [{ json: out }];
